public class Diagonales {
    public static void main(String[] args) {
        int[][] matriz = {{1,2,3},{4,5,6},{7,8,9}};
        int n = matriz.length;
        int diagP = 0, diagS = 0;
        for (int i = 0; i < n; i++) {
            diagP += matriz[i][i];
            diagS += matriz[i][n - 1 - i];
        }
        System.out.println("Main diagonal: " + diagP);
        System.out.println("Secondary diagonal: " + diagS);
    }
}

