solution:
public class SelectionSort {
    static void seleccion(int[] arr) {
        int n = arr.length;
        for (int i = 0; i < n - 1; i++) {
            int minIdx = i;
            for (int j = i + 1; j < n; j++) {
                if (arr[j] < arr[minIdx]) minIdx = j;
            }
            int temp = arr[i];
            arr[i] = arr[minIdx];
            arr[minIdx] = temp;
        }
    }
    static void imprimir(int[] arr) {
        for (int n : arr) System.out.print(n + " ");
        System.out.println();
    }
    public static void main(String[] args) {
        int[] datos = {64, 25, 12, 22, 11};
        System.out.print("Original: "); imprimir(datos);
        seleccion(datos);
        System.out.print("Sorted: "); imprimir(datos);
    }
}

